package jira

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"regexp"
	"strings"
	"time"

	gojira "github.com/andygrunwald/go-jira/v2/cloud"
)

type Config struct {
	URL            string        `toml:"url"`
	Username       string        `toml:"username"`
	APIToken       string        `toml:"api_token"`
	Project        string        `toml:"project"`
	IssueType      string        `toml:"issue_type"`
	PollInterval   time.Duration `toml:"poll_interval"`
	ApprovedStatus string        `toml:"approved_status"`
	RejectedStatus string        `toml:"rejected_status"`
}

func (c *Config) ApplyDefaults() {
	if c.IssueType == "" {
		c.IssueType = "Task"
	}
	if c.PollInterval == 0 {
		c.PollInterval = 30 * time.Second
	}
	if c.ApprovedStatus == "" {
		c.ApprovedStatus = "Approved"
	}
	if c.RejectedStatus == "" {
		c.RejectedStatus = "Rejected"
	}
}

func (c *Config) Validate() error {
	if c.URL == "" {
		return fmt.Errorf("url is required")
	}
	if c.Project == "" {
		return fmt.Errorf("project is required")
	}
	if c.Username == "" || c.APIToken == "" {
		return fmt.Errorf("username and api_token are required")
	}
	return nil
}

type Status int

const (
	StatusOpen Status = iota
	StatusApproved
	StatusRejected
)

func (s Status) String() string {
	switch s {
	case StatusApproved:
		return "approved"
	case StatusRejected:
		return "rejected"
	}
	return "open"
}

type TicketInput struct {
	RequestID   string
	User        string
	Roles       []string
	Reason      string
	Score       int
	Tier        string
	Components  map[string]int
	AIReasoning string
	Escalation  bool
}

// reqIDRE extracts a Teleport access-request ID from a Jira ticket
// description we created via buildDescription. The character class between
// the colon and the capture tolerates Jira wiki bold markers (e.g. the
// "*" that closes "*Teleport Request ID:*") as well as plain whitespace,
// so rehydration survives formatting tweaks to the description template.
var reqIDRE = regexp.MustCompile(`Teleport Request ID:[^A-Za-z0-9-]*([A-Za-z0-9-]+)`)

type Client struct {
	cfg  Config
	jira *gojira.Client
}

func New(cfg Config) (*Client, error) {
	tp := gojira.BasicAuthTransport{Username: cfg.Username, APIToken: cfg.APIToken}
	jc, err := gojira.NewClient(cfg.URL, tp.Client())
	if err != nil {
		return nil, err
	}
	return &Client{cfg: cfg, jira: jc}, nil
}

func (c *Client) CreateITSMTicket(ctx context.Context, in TicketInput) (string, error) {
	if c.cfg.Project == "" {
		return "", fmt.Errorf("jira project key is empty")
	}
	if c.cfg.IssueType == "" {
		return "", fmt.Errorf("jira issue type is empty")
	}
	if in.RequestID == "" {
		return "", fmt.Errorf("request id is empty")
	}

	labels := []string{"teleport", "teleport-access"}
	if in.Tier != "" {
		labels = append(labels, "tier-"+strings.ToLower(in.Tier))
	}
	if in.Escalation {
		labels = append(labels, "teleport-escalation")
	}

	summary := fmt.Sprintf("[teleport] Access request %s - %s", in.RequestID, in.Tier)
	if in.Escalation {
		summary = fmt.Sprintf("[teleport][escalation] Session escalation %s - %s", in.RequestID, in.Tier)
	}

	issue := &gojira.Issue{
		Fields: &gojira.IssueFields{
			Project:     gojira.Project{Key: c.cfg.Project},
			Type:        gojira.IssueType{Name: c.cfg.IssueType},
			Summary:     summary,
			Description: buildDescription(in),
			Labels:      labels,
		},
	}

	// Serialise the outgoing issue only when the debug log level is
	// active; marshaling runs on every ticket creation otherwise and
	// leaks request/requester detail to an unstructured stream.
	if slog.Default().Enabled(ctx, slog.LevelDebug) {
		reqBody, err := json.MarshalIndent(issue, "", "  ")
		if err != nil {
			return "", fmt.Errorf("marshal jira issue: %w", err)
		}
		slog.DebugContext(ctx, "creating jira issue",
			"request_id", in.RequestID,
			"project", c.cfg.Project,
			"body", string(reqBody))
	}

	created, resp, err := c.jira.Issue.Create(ctx, issue)
	if err != nil {
		if resp != nil && resp.Body != nil && slog.Default().Enabled(ctx, slog.LevelDebug) {
			body, _ := io.ReadAll(resp.Body)
			slog.DebugContext(ctx, "jira error response",
				"request_id", in.RequestID,
				"status", resp.StatusCode,
				"body", string(body))
		}
		return "", fmt.Errorf("create jira issue: %w", err)
	}

	if created == nil {
		return "", fmt.Errorf("jira returned nil issue without error")
	}

	return created.Key, nil
}

func (c *Client) TicketStatus(ctx context.Context, key string) (Status, error) {
	issue, _, err := c.jira.Issue.Get(ctx, key, nil)
	if err != nil {
		return StatusOpen, err
	}
	if issue.Fields == nil || issue.Fields.Status == nil {
		return StatusOpen, nil
	}
	switch issue.Fields.Status.Name {
	case c.cfg.ApprovedStatus:
		return StatusApproved, nil
	case c.cfg.RejectedStatus:
		return StatusRejected, nil
	}
	return StatusOpen, nil
}

func (c *Client) ListOpenTeleportTickets(ctx context.Context) (map[string]string, error) {
	jql := fmt.Sprintf(`project = %q AND labels = teleport AND status not in (%q, %q)`,
		c.cfg.Project, c.cfg.ApprovedStatus, c.cfg.RejectedStatus)
	issues, _, err := c.jira.Issue.Search(ctx, jql, nil)
	if err != nil {
		return nil, err
	}
	out := map[string]string{}
	for _, iss := range issues {
		if iss.Fields == nil {
			continue
		}
		m := reqIDRE.FindStringSubmatch(iss.Fields.Description)
		if len(m) < 2 {
			continue
		}
		out[m[1]] = iss.Key
	}
	return out, nil
}

func buildDescription(in TicketInput) string {
	var sb strings.Builder
	if in.Escalation {
		sb.WriteString("h2. Teleport Session Escalation Review\n\n")
		sb.WriteString("{panel:title=Session escalation}This request is a mid-session privilege bump — please prioritise review.{panel}\n\n")
	} else {
		sb.WriteString("h2. Teleport Access Request Review\n\n")
	}
	fmt.Fprintf(&sb, "* *Teleport Request ID:* %s\n", in.RequestID)
	fmt.Fprintf(&sb, "* *Requester:* %s\n", in.User)
	fmt.Fprintf(&sb, "* *Roles requested:* %s\n", strings.Join(in.Roles, ", "))
	fmt.Fprintf(&sb, "* *Risk score:* %d\n", in.Score)
	fmt.Fprintf(&sb, "* *Risk tier:* %s\n\n", in.Tier)

	sb.WriteString("h3. Request reason\n")
	sb.WriteString("{code}\n")
	sb.WriteString(in.Reason)
	sb.WriteString("\n{code}\n\n")

	if len(in.Components) > 0 {
		sb.WriteString("h3. Risk components\n")
		for k, v := range in.Components {
			fmt.Fprintf(&sb, "* %s: +%d\n", k, v)
		}
		sb.WriteString("\n")
	}

	if in.AIReasoning != "" {
		sb.WriteString("h3. AI reasoning\n")
		sb.WriteString("{quote}\n")
		sb.WriteString(in.AIReasoning)
		sb.WriteString("\n{quote}\n\n")
	}

	sb.WriteString("h3. SRE action required\n")
	sb.WriteString("Transition this ticket to the configured approved or rejected status to resolve the Teleport access request.\n")

	return sb.String()
}

