1	// Package reputation tracks per-user reputation scores derived from the
2	// quality of Teleport access requests. State is persisted to a local JSON
3	// file so no external database is required.
4	package reputation
5	
6	import (
7		"context"
8		"encoding/json"
9		"errors"
10		"fmt"
11		"io/fs"
12		"os"
13		"path/filepath"
14		"sync"
15	)
16	
17	type Config struct {
18		PersistPath            string `toml:"persist_path"`
19		StartingScore          int    `toml:"starting_score"`
20		FloorScore             int    `toml:"floor_score"`
21		CeilingScore           int    `toml:"ceiling_score"`
22		PenaltyMissingCUSTX    int    `toml:"penalty_missing_custx"`
23		PenaltyThinDescription int    `toml:"penalty_thin_description"`
24	}
25	
26	func (c *Config) ApplyDefaults() {
27		if c.StartingScore == 0 {
28			c.StartingScore = 100
29		}
30		if c.CeilingScore == 0 {
31			c.CeilingScore = 100
32		}
33		if c.PenaltyMissingCUSTX == 0 {
34			c.PenaltyMissingCUSTX = 10
35		}
36		if c.PenaltyThinDescription == 0 {
37			c.PenaltyThinDescription = 5
38		}
39	}
40	
41	func (c *Config) Validate() error {
42		if c.FloorScore > c.CeilingScore {
43			return fmt.Errorf("floor_score (%d) must be <= ceiling_score (%d)", c.FloorScore, c.CeilingScore)
44		}
45		if c.StartingScore < c.FloorScore || c.StartingScore > c.CeilingScore {
46			return fmt.Errorf("starting_score (%d) must be within [%d, %d]", c.StartingScore, c.FloorScore, c.CeilingScore)
47		}
48		return nil
49	}
50	
51	type Penalty struct {
52		Reason string
53		Amount int
54	}
55	
56	type Assessment struct {
57		Score     int
58		Previous  int
59		Penalties []Penalty
60	}
61	
62	type Store struct {
63		cfg Config
64		mu  sync.RWMutex
65		rep map[string]int
66	}
67	
68	func NewStore(cfg Config) (*Store, error) {
69		s := &Store{cfg: cfg, rep: make(map[string]int, 64)}
70		if cfg.PersistPath != "" {
71			if err := s.load(); err != nil {
72				return nil, err
73			}
74		}
75		return s, nil
76	}
77	
78	// Score returns the current reputation for user, or StartingScore if unseen.
79	func (s *Store) Score(user string) int {
80		s.mu.RLock()
81		defer s.mu.RUnlock()
82		if v, ok := s.rep[user]; ok {
83			return v
84		}
85		return s.cfg.StartingScore
86	}
87	
88	// Range invokes fn for every tracked user under a read lock. Do not call
89	// back into the store from fn or you will deadlock.
90	func (s *Store) Range(fn func(user string, score int)) {
91		s.mu.RLock()
92		defer s.mu.RUnlock()
93		for u, sc := range s.rep {
94			fn(u, sc)
95		}
96	}
97	
98	// Assess translates risk components into configured penalties, docks the
99	// user's score, clamps to [floor, ceiling], persists to disk, and returns
100	// the updated assessment. A component map with no bad signals is a no-op.
101	func (s *Store) Assess(ctx context.Context, user string, components map[string]int) (Assessment, error) {
102		return s.apply(ctx, user, s.penaltiesFor(components))
103	}
104	
105	func (s *Store) penaltiesFor(components map[string]int) []Penalty {
106		penalties := make([]Penalty, 0, 2)
107		if _, ok := components["missing_custx_ticket"]; ok && s.cfg.PenaltyMissingCUSTX > 0 {
108			penalties = append(penalties, Penalty{Reason: "missing_custx_ticket", Amount: s.cfg.PenaltyMissingCUSTX})
109		}
110		if _, ok := components["thin_description"]; ok && s.cfg.PenaltyThinDescription > 0 {
111			penalties = append(penalties, Penalty{Reason: "thin_description", Amount: s.cfg.PenaltyThinDescription})
112		}
113		return penalties
114	}
115	
116	func (s *Store) apply(ctx context.Context, user string, penalties []Penalty) (Assessment, error) {
117		// Holding the write lock across the persist serializes concurrent
118		// apply calls. Without it, two in-flight persists can each snapshot
119		// independently and the slower os.Rename can land last, silently
120		// overwriting the newer on-disk state with a stale view.
121		s.mu.Lock()
122		defer s.mu.Unlock()
123	
124		prev, ok := s.rep[user]
125		if !ok {
126			prev = s.cfg.StartingScore
127		}
128		score := prev
129		for _, p := range penalties {
130			score -= p.Amount
131		}
132		if score < s.cfg.FloorScore {
133			score = s.cfg.FloorScore
134		}
135		if score > s.cfg.CeilingScore {
136			score = s.cfg.CeilingScore
137		}
138		s.rep[user] = score
139	
140		assessment := Assessment{Score: score, Previous: prev, Penalties: penalties}
141		if s.cfg.PersistPath == "" || len(penalties) == 0 {
142			return assessment, nil
143		}
144		if err := s.persistLocked(ctx); err != nil {
145			return assessment, fmt.Errorf("persist reputation: %w", err)
146		}
147		return assessment, nil
148	}
149	
150	func (s *Store) load() error {
151		data, err := os.ReadFile(s.cfg.PersistPath)
152		if err != nil {
153			if errors.Is(err, fs.ErrNotExist) {
154				return nil
155			}
156			return fmt.Errorf("read reputation state: %w", err)
157		}
158		if len(data) == 0 {
159			return nil
160		}
161		var rep map[string]int
162		if err := json.Unmarshal(data, &rep); err != nil {
163			return fmt.Errorf("parse reputation state: %w", err)
164		}
165		s.rep = rep
166		return nil
167	}
168	
169	// persistLocked writes the in-memory reputation map to disk via a
170	// tmp-file + atomic rename. The caller MUST hold s.mu (write lock);
171	// that's how we keep concurrent persists from racing on the rename.
172	func (s *Store) persistLocked(_ context.Context) error {
173		data, err := json.Marshal(s.rep)
174		if err != nil {
175			return err
176		}
177	
178		dir := filepath.Dir(s.cfg.PersistPath)
179		if err := os.MkdirAll(dir, 0o755); err != nil {
180			return err
181		}
182		tmp, err := os.CreateTemp(dir, ".reputation.*.tmp")
183		if err != nil {
184			return err
185		}
186		tmpPath := tmp.Name()
187		defer os.Remove(tmpPath)
188	
189		if _, err := tmp.Write(data); err != nil {
190			tmp.Close()
191			return err
192		}
193		if err := tmp.Chmod(0o600); err != nil {
194			tmp.Close()
195			return err
196		}
197		if err := tmp.Sync(); err != nil {
198			tmp.Close()
199			return err
200		}
201		if err := tmp.Close(); err != nil {
202			return err
203		}
204		return os.Rename(tmpPath, s.cfg.PersistPath)
205	}
