// Package reputation tracks per-user reputation scores derived from the
// quality of Teleport access requests. State is persisted to a local JSON
// file so no external database is required.
package reputation

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sync"
)

type Config struct {
	PersistPath            string `toml:"persist_path"`
	StartingScore          int    `toml:"starting_score"`
	FloorScore             int    `toml:"floor_score"`
	CeilingScore           int    `toml:"ceiling_score"`
	PenaltyMissingCUSTX    int    `toml:"penalty_missing_custx"`
	PenaltyThinDescription int    `toml:"penalty_thin_description"`
}

func (c *Config) ApplyDefaults() {
	if c.StartingScore == 0 {
		c.StartingScore = 100
	}
	if c.CeilingScore == 0 {
		c.CeilingScore = 100
	}
	if c.PenaltyMissingCUSTX == 0 {
		c.PenaltyMissingCUSTX = 10
	}
	if c.PenaltyThinDescription == 0 {
		c.PenaltyThinDescription = 5
	}
}

func (c *Config) Validate() error {
	if c.FloorScore > c.CeilingScore {
		return fmt.Errorf("floor_score (%d) must be <= ceiling_score (%d)", c.FloorScore, c.CeilingScore)
	}
	if c.StartingScore < c.FloorScore || c.StartingScore > c.CeilingScore {
		return fmt.Errorf("starting_score (%d) must be within [%d, %d]", c.StartingScore, c.FloorScore, c.CeilingScore)
	}
	return nil
}

type Penalty struct {
	Reason string
	Amount int
}

type Assessment struct {
	Score     int
	Previous  int
	Penalties []Penalty
}

type Store struct {
	cfg Config
	mu  sync.RWMutex
	rep map[string]int
}

func NewStore(cfg Config) (*Store, error) {
	s := &Store{cfg: cfg, rep: make(map[string]int, 64)}
	if cfg.PersistPath != "" {
		if err := s.load(); err != nil {
			return nil, err
		}
	}
	return s, nil
}

// Score returns the current reputation for user, or StartingScore if unseen.
func (s *Store) Score(user string) int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	if v, ok := s.rep[user]; ok {
		return v
	}
	return s.cfg.StartingScore
}

// Range invokes fn for every tracked user under a read lock. Do not call
// back into the store from fn or you will deadlock.
func (s *Store) Range(fn func(user string, score int)) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	for u, sc := range s.rep {
		fn(u, sc)
	}
}

// Assess translates risk components into configured penalties, docks the
// user's score, clamps to [floor, ceiling], persists to disk, and returns
// the updated assessment. A component map with no bad signals is a no-op.
func (s *Store) Assess(ctx context.Context, user string, components map[string]int) (Assessment, error) {
	return s.apply(ctx, user, s.penaltiesFor(components))
}

func (s *Store) penaltiesFor(components map[string]int) []Penalty {
	penalties := make([]Penalty, 0, 2)
	if _, ok := components["missing_custx_ticket"]; ok && s.cfg.PenaltyMissingCUSTX > 0 {
		penalties = append(penalties, Penalty{Reason: "missing_custx_ticket", Amount: s.cfg.PenaltyMissingCUSTX})
	}
	if _, ok := components["thin_description"]; ok && s.cfg.PenaltyThinDescription > 0 {
		penalties = append(penalties, Penalty{Reason: "thin_description", Amount: s.cfg.PenaltyThinDescription})
	}
	return penalties
}

func (s *Store) apply(ctx context.Context, user string, penalties []Penalty) (Assessment, error) {
	// Holding the write lock across the persist serializes concurrent
	// apply calls. Without it, two in-flight persists can each snapshot
	// independently and the slower os.Rename can land last, silently
	// overwriting the newer on-disk state with a stale view.
	s.mu.Lock()
	defer s.mu.Unlock()

	prev, ok := s.rep[user]
	if !ok {
		prev = s.cfg.StartingScore
	}
	score := prev
	for _, p := range penalties {
		score -= p.Amount
	}
	if score < s.cfg.FloorScore {
		score = s.cfg.FloorScore
	}
	if score > s.cfg.CeilingScore {
		score = s.cfg.CeilingScore
	}
	s.rep[user] = score

	assessment := Assessment{Score: score, Previous: prev, Penalties: penalties}
	if s.cfg.PersistPath == "" || len(penalties) == 0 {
		return assessment, nil
	}
	if err := s.persistLocked(ctx); err != nil {
		return assessment, fmt.Errorf("persist reputation: %w", err)
	}
	return assessment, nil
}

func (s *Store) load() error {
	data, err := os.ReadFile(s.cfg.PersistPath)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil
		}
		return fmt.Errorf("read reputation state: %w", err)
	}
	if len(data) == 0 {
		return nil
	}
	var rep map[string]int
	if err := json.Unmarshal(data, &rep); err != nil {
		return fmt.Errorf("parse reputation state: %w", err)
	}
	s.rep = rep
	return nil
}

// persistLocked writes the in-memory reputation map to disk via a
// tmp-file + atomic rename. The caller MUST hold s.mu (write lock);
// that's how we keep concurrent persists from racing on the rename.
func (s *Store) persistLocked(_ context.Context) error {
	data, err := json.Marshal(s.rep)
	if err != nil {
		return err
	}

	dir := filepath.Dir(s.cfg.PersistPath)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, ".reputation.*.tmp")
	if err != nil {
		return err
	}
	tmpPath := tmp.Name()
	defer os.Remove(tmpPath)

	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Chmod(0o600); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmpPath, s.cfg.PersistPath)
}

