package ai

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
)

type AnthropicConfig struct {
	APIKey string `toml:"api_key"`
	Model  string `toml:"model"`
}

type Anthropic struct {
	cfg    AnthropicConfig
	client *http.Client
}

func NewAnthropic(cfg AnthropicConfig) *Anthropic {
	if cfg.Model == "" {
		cfg.Model = "claude-sonnet-4-6"
	}
	return &Anthropic{cfg: cfg, client: &http.Client{}}
}

func (a *Anthropic) Assess(ctx context.Context, req ScoreRequest) (*Assessment, error) {
	body, err := json.Marshal(map[string]any{
		"model":      a.cfg.Model,
		"max_tokens": 1024,
		"system": []map[string]any{
			{
				"type":          "text",
				"text":          SystemPrompt,
				"cache_control": map[string]string{"type": "ephemeral"},
			},
		},
		"messages": []map[string]any{
			{"role": "user", "content": UserPrompt(req)},
		},
	})
	if err != nil {
		return nil, err
	}
	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost,
		"https://api.anthropic.com/v1/messages", bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	httpReq.Header.Set("Content-Type", "application/json")
	httpReq.Header.Set("x-api-key", a.cfg.APIKey)
	httpReq.Header.Set("anthropic-version", "2023-06-01")

	resp, err := a.client.Do(httpReq)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 300 {
		raw, _ := io.ReadAll(resp.Body)
		return nil, fmt.Errorf("anthropic %d: %s", resp.StatusCode, raw)
	}
	var out struct {
		Content []struct {
			Text string `json:"text"`
			Type string `json:"type"`
		} `json:"content"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return nil, err
	}
	for _, c := range out.Content {
		if c.Type == "text" {
			return parseAssessment(c.Text)
		}
	}
	return nil, fmt.Errorf("no text content in anthropic response")
}

package ruth

import (
	"os"
	"path/filepath"
	"testing"
)

func writeConfig(t *testing.T, body string) string {
	t.Helper()
	dir := t.TempDir()
	path := filepath.Join(dir, "ruth.toml")
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatalf("write config: %v", err)
	}
	return path
}

// Explicit zeros in TOML must not be silently resurrected by ApplyDefaults.
// This is the integration-level expression of the bug where a user who
// wants to disable a penalty by setting it to 0 would otherwise get the
// default value back.
func TestLoadConfig_ExplicitZeroDisablesDefaultBackedField(t *testing.T) {
	path := writeConfig(t, `
[teleport]
addr          = "proxy.example.com:443"
identity_file = "/tmp/ruth.pem"

[ai]
provider = "anthropic"

[ai.anthropic]
api_key = "sk-test"

[jira]
url       = "https://example.atlassian.net"
username  = "bot@example.com"
api_token = "token"
project   = "ITSM"

[risk]
ticket_threshold     = 0
escalation_threshold = 0

[reputation]
penalty_missing_custx    = 0
penalty_thin_description = 0
`)

	cfg, err := LoadConfig(path)
	if err != nil {
		t.Fatalf("LoadConfig: %v", err)
	}

	if cfg.Reputation.PenaltyMissingCUSTX != 0 {
		t.Errorf("PenaltyMissingCUSTX = %d, want 0 (TOML disable must win over default)", cfg.Reputation.PenaltyMissingCUSTX)
	}
	if cfg.Reputation.PenaltyThinDescription != 0 {
		t.Errorf("PenaltyThinDescription = %d, want 0", cfg.Reputation.PenaltyThinDescription)
	}
	if cfg.Risk.TicketThreshold != 0 {
		t.Errorf("Risk.TicketThreshold = %d, want 0", cfg.Risk.TicketThreshold)
	}
	if cfg.Risk.EscalationThreshold != 0 {
		t.Errorf("Risk.EscalationThreshold = %d, want 0", cfg.Risk.EscalationThreshold)
	}
}

// Absent keys should still receive defaults — flipping the layering order
// must not regress the common case of "I didn't set this; give me sane defaults".
func TestLoadConfig_AbsentKeysGetDefaults(t *testing.T) {
	path := writeConfig(t, `
[teleport]
addr          = "proxy.example.com:443"
identity_file = "/tmp/ruth.pem"

[ai]
provider = "anthropic"

[ai.anthropic]
api_key = "sk-test"

[jira]
url       = "https://example.atlassian.net"
username  = "bot@example.com"
api_token = "token"
project   = "ITSM"
`)

	cfg, err := LoadConfig(path)
	if err != nil {
		t.Fatalf("LoadConfig: %v", err)
	}

	if got, want := cfg.Risk.TicketThreshold, 25; got != want {
		t.Errorf("Risk.TicketThreshold = %d, want %d (default)", got, want)
	}
	if got, want := cfg.Risk.EscalationThreshold, 15; got != want {
		t.Errorf("Risk.EscalationThreshold = %d, want %d (default)", got, want)
	}
	if got, want := cfg.Reputation.PenaltyMissingCUSTX, 10; got != want {
		t.Errorf("PenaltyMissingCUSTX = %d, want %d (default)", got, want)
	}
	if got, want := cfg.Reputation.StartingScore, 100; got != want {
		t.Errorf("StartingScore = %d, want %d (default)", got, want)
	}
	if got, want := cfg.Log.Level, "info"; got != want {
		t.Errorf("Log.Level = %q, want %q (default)", got, want)
	}
}

// Env var overrides still take precedence over both TOML and defaults,
// including when the TOML value is an explicit zero.
func TestLoadConfig_EnvBeatsTOMLZero(t *testing.T) {
	t.Setenv("RUTH_RISK_TICKET_THRESHOLD", "42")
	path := writeConfig(t, `
[teleport]
addr          = "proxy.example.com:443"
identity_file = "/tmp/ruth.pem"

[ai]
provider = "anthropic"

[ai.anthropic]
api_key = "sk-test"

[jira]
url       = "https://example.atlassian.net"
username  = "bot@example.com"
api_token = "token"
project   = "ITSM"

[risk]
ticket_threshold = 0
`)

	cfg, err := LoadConfig(path)
	if err != nil {
		t.Fatalf("LoadConfig: %v", err)
	}
	if cfg.Risk.TicketThreshold != 42 {
		t.Errorf("Risk.TicketThreshold = %d, want 42 (env > TOML > default)", cfg.Risk.TicketThreshold)
	}
}

