package ruth

import (
	"testing"
	"time"

	"ruth/ai"
	"ruth/jira"
	"ruth/reputation"
	"ruth/risk"
	"ruth/telemetry"
)

func TestApplyEnv_Overrides(t *testing.T) {
	t.Setenv("RUTH_DRY_RUN", "true")
	t.Setenv("RUTH_TELEPORT_ADDR", "env-proxy.example.com:443")
	t.Setenv("RUTH_TELEPORT_IDENTITY_FILE", "/env/identity.pem")
	t.Setenv("RUTH_AI_PROVIDER", "bedrock")
	t.Setenv("RUTH_AI_ANTHROPIC_API_KEY", "sk-from-env")
	t.Setenv("RUTH_AI_BEDROCK_REGION", "us-east-2")
	t.Setenv("RUTH_RISK_TICKET_THRESHOLD", "42")
	t.Setenv("RUTH_RISK_ESCALATION_THRESHOLD", "7")
	t.Setenv("RUTH_JIRA_POLL_INTERVAL", "2m")
	t.Setenv("RUTH_TELEMETRY_ENABLED", "true")
	t.Setenv("RUTH_REPUTATION_STARTING_SCORE", "80")

	cfg := &Config{
		DryRun:   false,
		Teleport: TeleportConfig{Addr: "old:443", IdentityFile: "/old.pem"},
		AI: ai.Config{
			Provider:  "anthropic",
			Anthropic: ai.AnthropicConfig{APIKey: "sk-old"},
			Bedrock:   ai.BedrockConfig{Region: "us-west-2"},
		},
		Risk:       risk.Config{TicketThreshold: 25, EscalationThreshold: 15},
		Jira:       jira.Config{PollInterval: 30 * time.Second},
		Telemetry:  telemetry.Config{Enabled: false},
		Reputation: reputation.Config{StartingScore: 100},
	}

	if err := applyEnv(cfg); err != nil {
		t.Fatalf("applyEnv: %v", err)
	}

	checks := []struct {
		name string
		got  any
		want any
	}{
		{"dry_run", cfg.DryRun, true},
		{"teleport.addr", cfg.Teleport.Addr, "env-proxy.example.com:443"},
		{"teleport.identity_file", cfg.Teleport.IdentityFile, "/env/identity.pem"},
		{"ai.provider", cfg.AI.Provider, "bedrock"},
		{"ai.anthropic.api_key", cfg.AI.Anthropic.APIKey, "sk-from-env"},
		{"ai.bedrock.region", cfg.AI.Bedrock.Region, "us-east-2"},
		{"risk.ticket_threshold", cfg.Risk.TicketThreshold, 42},
		{"risk.escalation_threshold", cfg.Risk.EscalationThreshold, 7},
		{"jira.poll_interval", cfg.Jira.PollInterval, 2 * time.Minute},
		{"telemetry.enabled", cfg.Telemetry.Enabled, true},
		{"reputation.starting_score", cfg.Reputation.StartingScore, 80},
	}
	for _, c := range checks {
		if c.got != c.want {
			t.Errorf("%s = %v, want %v", c.name, c.got, c.want)
		}
	}
}

func TestApplyEnv_NoEnvLeavesConfigUntouched(t *testing.T) {
	cfg := &Config{
		Teleport: TeleportConfig{Addr: "untouched:443"},
		Risk:     risk.Config{TicketThreshold: 25},
	}
	if err := applyEnv(cfg); err != nil {
		t.Fatalf("applyEnv: %v", err)
	}
	if cfg.Teleport.Addr != "untouched:443" {
		t.Errorf("Addr = %q, want untouched:443", cfg.Teleport.Addr)
	}
	if cfg.Risk.TicketThreshold != 25 {
		t.Errorf("TicketThreshold = %d, want 25", cfg.Risk.TicketThreshold)
	}
}

func TestApplyEnv_InvalidValue(t *testing.T) {
	t.Setenv("RUTH_RISK_TICKET_THRESHOLD", "not-a-number")
	cfg := &Config{Risk: risk.Config{TicketThreshold: 25}}
	err := applyEnv(cfg)
	if err == nil {
		t.Fatal("applyEnv: expected error for non-numeric override, got nil")
	}
	if !contains(err.Error(), "RUTH_RISK_TICKET_THRESHOLD") {
		t.Errorf("error should name the offending env var, got: %v", err)
	}
}

func TestApplyEnv_MapFieldSkipped(t *testing.T) {
	// Maps can't be expressed as a single env var; the helper must skip
	// them silently rather than choke on an env var aimed at one.
	t.Setenv("RUTH_RISK_ESCALATION_THRESHOLDS", "this-would-not-parse")
	cfg := &Config{
		Risk: risk.Config{
			EscalationThresholds: map[string]int{"sre-admin": 5},
		},
	}
	if err := applyEnv(cfg); err != nil {
		t.Fatalf("applyEnv: %v", err)
	}
	if got := cfg.Risk.EscalationThresholds["sre-admin"]; got != 5 {
		t.Errorf("EscalationThresholds[sre-admin] = %d, want 5", got)
	}
}

func contains(haystack, needle string) bool {
	for i := 0; i+len(needle) <= len(haystack); i++ {
		if haystack[i:i+len(needle)] == needle {
			return true
		}
	}
	return false
}

